@ GT Advance 3 - menu span completion
@ Region: file offset 0x00FF78-0x015CB4 (VMA 0x0800FF78-0x08015CB4).
@ Pure Thumb, ARMCC; closes the big raw menu span (menu_fa24.s ends at
@ 0xFF78; rec35_init.s resumes at 0x015CB4). Transcribed from baserom.gba
@ via objdump; byte-exact (make SHA gate). Unconverted targets keep numeric
@ `bl 0x0800XXXX` form. Pools at original offsets.
@
@ Function map (117 functions; regenerated by tools/objdump2gas.py and
@ spliced back -- all branch/BL/pool labels now automated):
@  Entry:
@   sub_0800FF78    - menu record-49 entry dispatcher: gate cells
@                     s16[0x03001780+0xFBC] {1|7(+0x1078==2)} -> sub_0800F794;
@                     8-entry jump table @0xFFD0 on u16[rec+0xD6] -> the seven
@                     setup twins below; then cursor-record wiring via
@                     sub_08007ABC + 0x080258A8 + 0x08026F30/50 and clears
@                     rec+0xCC/0xCE/0xDC.
@  Seven parallel screen-setup twins (one per jump-table case):
@   sub_080010088/0101FC/010370/0104F0/010644/0107CC
@                    - ~370-390B each; repeated sub_08007ABC record-cell
@                      sends + menu leaves sub_0800F8B4/F744/F810.
@  Leaves:
@   sub_0800108D4/0108F0 - tiny pure accessor leaves (28/36B, no calls).
@   sub_080010914/010940/01096C - row/col wrappers over the two leaves.
@   sub_0800109D4 - 740B setup driving the leaves + sub_080011214/0113A0.
@   sub_080010CB8/010F3C/0110A0/011214/0113A0/011484/0115E0/0116DC
@                    - screen setup family calling sub_0800F744/F700/F6D0/
@                      F7EC/F810 + sub_08007ABC (record cell sends).
@  Course-record fillers (sub_08007B18 placement helper):
@   sub_080011784/011854/0118DC/011958, sub_080011B48/011CBC/011CFC/
@   011D48/011DC4/011E10/011E58/011EE0/011F68/011FF0, sub_080012A44/
@   012AC0/012B34/012B68, sub_080013950/0139F0/013AA8/013AF4,
@   sub_0800146D0/01479C/014A08, sub_080015930/0159AC.
@  Menu-item record builders (7 screens; each calls the fillers above +
@  sub_0800F778 + sub_0800D97C/sub_0800DBE8 + no-op sub_080012574):
@   sub_080012034/0120A8/0121A8/01226C/0122E0/0123D8/0124EC.
@  Phase dispatchers (12-entry jump tables, `subs r0,#1; cmp #11`):
@   sub_0800125C4, sub_080012DA0, sub_080013EB0, sub_080014BD0,
@   sub_080015154, sub_080015BA0.
