@   sub_080012D54 - countdown tick (gate 0xFBC==3 -> 0x08002140, counter
@                   at rec+148 capped 180 -> scene event 21).
@   sub_080015B54 - same countdown pattern (rec+172, cap 180, event 21).
@   sub_080015230 - rec+136 flag reset; gate 0xFBC==3 -> 0x08002140, then
@                   sub_08004B68 record id 27..30 -> rec+132 {1|6}.
@   sub_08001549C - record screen init (sound 1 via 0x0802B368, rec+16=10,
@                   rec+20=0); used by the 0x154E0/0x15620/0x1573C trio.
@   sub_080015A0C/015AB0 - record body builders (0x15930/0x159AC fillers +
@                   sub_08007C68/0xDC7C/0xDBE8 + sub_0800D97C).
@  Course/save bridge setup (resource attach + save-alloc sub_0800572C):
@   sub_080012854, sub_080013108, sub_0800133E4, sub_0800141AC,
@   sub_080014488, sub_080014C88, sub_080015304.
